Definition STAT : list kentry := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!3,>+H!2,I'J'K!3,>+H!3,L!2,M!1,6,N!1,0|D6d7b8;}8!1,6'O!1,B+H").
