Definition WREGS_XS : list (expr * Z * expr) := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S20!2+?+1+F!2+?0+1!3,>1!4,@0+1!4,@+1+F'S!1,0|48;!1,6!1,0|30;!1,B1").
Definition WREGS_SETEC : list (expr * Z * expr) := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S40!2+?+1+F!2+?0+1!1,6,N|10;!3,>1!4,@0+1!4,@+1+F'[,N!1,6!1,0|40;!3,>1!4,@0+1!4,@+1+F2'\!1,6!1,03!3,>1!4,@0+1!4,@+1+F2'^0!1,6!1,0|9020;!1,B1").
