Definition isSome {A} (o : option A) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S01<scd;$A;R{cd;$o;R!1+^3#1-^3RN$o;R!1+^3#2+^4#12$a;R#2,^5,^6").
Definition has := CC.has_cell.
(* [comment removed for export] *)
Definition KX (j : nat) : expr := if Nat.eqb j 3 then kE else ELit 16384.
Definition KXR (j : nat) : kentry := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S10!1,0|>0000;$j;R+^7-^4RN$~R+^4+H!2'^8#1}32!3,;'U!1,0,8!1,0|=1fff;!3,;'U00").
