Definition exs (i : nat) (a0 a1 v280 vbf : expr) (rd : Z) (gc : kentry) (xs : list kentry) (ii : nat) (ps : SR.post_spec) : bool :=
  let cells := SR.ps_cells ps in
  (Nat.eqb ii i && CL.ps_reg_is ps 10 a0 && CL.ps_reg_is ps 11 a1 && has cells (KWord (SA RE 280) 8 v280) && has cells (KWord (SA RE 288) 8 (ELit 0)) && has cells (KWord (SA RE 296) 1 vbf)
   && has cells (KWord (SA isE 152) 4 (ELit rd)) && has cells gc && forallb (has cells) xs)%bool.
Definition GENT : kentry := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!3,L!2,M':!1,0|508;}8'T").
Definition exit_shape (i : nat) (ps : SR.post_spec) : bool :=
  (exs 1 (ELit 0) (ELit 0) deE bfE 2 GENT [] i ps
   || exs 2 chE kE (ADDE chE kE) bfE 2 GCELL [KRange bfE 0 0; KRange kE 0 16383] i ps
   || exs 2 chE (ELit 0) (ADDE chE kE) bfE 2 GCELL [KRange kE 0 0] i ps
   || exs 2 chE (ELit 16384) (ADDE chE (ELit 16384)) bfE 0 GCELL [KRange bfE 0 0; KRange kE 16384 16384] i ps
   || exs 3 (ADDE chE dE) (ADDE kE (NEGE dE)) (ADDE chE kE) (ELit 0) 2 GCELL [KRange kE 1 16383; KRange dE 0 4; KHALF] i ps      (* [comment removed for export] *)
   || exs 4 (ADDE chE dE) (ADDE (NEGE dE) (ELit 16384)) (ADDE chE (ELit 16384)) (ELit 0) 0 GCELL [KRange kE 16384 16384; KRange dE 0 4; KHALF] i ps
   || exs 5 (ELit 0) (ELit 0) (ADDE chE kE) bfE 2 GCELL [KRange kE 1 16383] i ps
   || exs 6 (ELit 0) (ELit 0) (ADDE chE (ELit 16384)) bfE 0 GCELL [KRange kE 16384 16384] i ps)%bool.
Definition leaf_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto _ _ => false
  | CC.TOther pc =>
      let cells := SR.ps_cells ps in
      (CH2.blocks_eqb (nth i G.BLS []) BLK0 && CHA.foot_chk GT.NF G.HDECL c BLK0 [] && CBA.regions_eqb (CC.cp_F c) CPF && Nat.leb (if Nat.leb 3 i then 62 else if Nat.leb 2 i then 38 else 37) (CC.cp_nx c) &&      (* [comment removed for export] *)
      match CH2.ret_of G.RETS i k with
      | Some j =>
          match nth_error G.CPS j with
          | Some cj =>
              (CH2.blocks_eqb (nth j G.BLS []) BLK0 &&
              if Z.eqb pc PC_XS then
                (Z.eqb (SR.ps_pc ps) PC_XS && Nat.eqb i 0 && Nat.eqb j 2
                 && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 2624 1 [] [] WREGS_XS NEWS_XS (Some kE) c ps cj BLK0 [] BLK0 [] with Some ci => Z.eqb (CH2.ci_csp ci) (-144) && Nat.eqb (CH2.ci_nx ci) 37 | None => false end
                 && CL.ps_reg_is ps 10 sbE && CL.ps_reg_is ps 11 chE && CL.ps_reg_is ps 12 (ELit 16384)
                 && has cells GENT && has cells (KWord (SA isE 152) 4 (ELit 0)))%bool
              else if Z.eqb pc PC_DET then
                (Z.eqb (SR.ps_pc ps) PC_DET && Nat.eqb i 2 && (Nat.eqb j 3 || Nat.eqb j 4)
                 && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 8256 1 BLK0 [] [] NEWS_DET (Some (ADDE chE dE)) c ps cj BLK0 [] BLK0 [] with Some ci => Z.eqb (CH2.ci_csp ci) (-48) && Nat.eqb (CH2.ci_nx ci) 55 | None => false end
                 && CL.ps_reg_is ps 10 chE && CL.ps_reg_is ps 11 (KX j) && has cells (KXR j) && has cells (KRange bfE 1 1))%bool      (* [comment removed for export] *)
              else if Z.eqb pc PC_SETEC then
                (Z.eqb (SR.ps_pc ps) PC_SETEC && ((Nat.eqb i 3 && Nat.eqb j 5) || (Nat.eqb i 4 && Nat.eqb j 6))
                 && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 1024 0 BLK0 [] WREGS_SETEC STAT (Some EE) c ps cj BLK0 [] BLK0 [] with Some ci => Z.eqb (CH2.ci_csp ci) (-48) | None => false end
                 && CL.ps_reg_is ps 10 EE && CL.ps_reg_is ps 11 (ELit 30) && has cells KERRK)%bool      (* [comment removed for export] *)
              else false)%bool
          | None => false
          end
      | None => (Z.eqb pc RETPC && CBA.exit_base_chk GT.NF RETPC c ps && exit_shape i ps)%bool
      end)%bool
  end.
